import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData, deleteExamData } from '../services/api'; // Assuming you have deleteExamData function

const ExamData = () => {
  const [franchiseId, setFranchiseId] = useState('');
  const [franchises, setFranchises] = useState([]);  // Store the list of franchises
  const [formData, setFormData] = useState({
    examName: '',
    date: '',
    studentsAttended: '',
  });
  const [examList, setExamList] = useState([]); // Store the list of exams for the selected franchise

  // Fetch franchises on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises(); // Assuming this function fetches the list of franchises
        setFranchises(response.data);  // Assuming the response contains an array of franchises
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []);  // Empty dependency array ensures it only runs once when the component mounts

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFranchiseChange = (e) => {
    setFranchiseId(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await updateExamData(franchiseId, formData); // Pass franchiseId along with form data
      alert('Exam data updated successfully!');
      setExamList([...examList, response.data]); // Add the new exam data to the list
      setFormData({
        examName: '',
        date: '',
        studentsAttended: '',
      }); // Clear the form after submission
    } catch (error) {
      alert('Error updating exam data: ' + error.response?.data?.message || error.message);
      console.error('Error:', error);  // Debugging: Log error
    }
  };

  const handleDelete = async (examId) => {
    try {
      await deleteExamData(franchiseId, examId); // Call the delete function with franchiseId and examId
      setExamList(examList.filter((exam) => exam._id !== examId)); // Remove the deleted exam from the list
      alert('Exam data deleted successfully!');
    } catch (error) {
      alert('Error deleting exam data: ' + error.response?.data?.message || error.message);
      console.error('Error:', error);
    }
  };

  const handleEdit = (exam) => {
    setFormData({
      examName: exam.examName,
      date: exam.date,
      studentsAttended: exam.studentsAttended,
    });
    setExamList(examList.filter((e) => e._id !== exam._id)); // Remove the exam from the list temporarily (since it's being edited)
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="franchiseId">Franchise ID:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={franchiseId}
            onChange={handleFranchiseChange}
            required
          >
            <option value="">Select Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} {/* Or whatever property represents the name */}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor="examName">Exam Name:</label>
          <input
            id="examName"
            name="examName"
            placeholder="Enter Exam Name"
            value={formData.examName}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="studentsAttended">Students Attended:</label>
          <input
            id="studentsAttended"
            name="studentsAttended"
            type="number"
            placeholder="Number of Students"
            value={formData.studentsAttended}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit">Update Exam Data</button>
      </form>

      <h2>Exam Data</h2>
      <ul>
        {examList.map((exam) => (
          <li key={exam._id}>
            <div>
              <h3>{exam.examName}</h3>
              <p>Date: {exam.date}</p>
              <p>Students Attended: {exam.studentsAttended}</p>
              <button onClick={() => handleEdit(exam)}>Edit</button>
              <button onClick={() => handleDelete(exam._id)}>Delete</button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ExamData;
